cd "/Users/lesurmatthis/dev/projet perso/collega/collega_app" && python3 - <<'EOF'
p='lib/core/ui/components/cg_verdict_bar.dart'
s=open(p).read()
old="""    return Row(children: [
      for (final (i, b) in buttons.indexed) ...[
        if (i > 0) const SizedBox(width: _gap),
        Expanded(child: b),
      ],
    ]);
  }
"""
new="""    // Sur une ligne, les trois libellés partagent une même échelle, réduite juste
    // assez pour que le plus long tienne (« Maîtrisé » à 1,6× sur 375 pt) : pas de
    // mot coupé, pas de tailles inégales d'un bouton à l'autre.
    return LayoutBuilder(builder: (context, constraints) {
      final scaler = MediaQuery.textScalerOf(context);
      final available = (constraints.maxWidth - 2 * _gap) / CgVerdict.values.length - _VerdictButtonState.chrome;
      var needed = 0.0;
      for (final v in CgVerdict.values) {
        final painter = TextPainter(
          text: TextSpan(text: v.label, style: CgType.head),
          textScaler: scaler,
          textDirection: TextDirection.ltr,
          maxLines: 1,
        )..layout();
        if (painter.width > needed) needed = painter.width;
        painter.dispose();
      }
      final row = Row(children: [
        for (final (i, b) in buttons.indexed) ...[
          if (i > 0) const SizedBox(width: _gap),
          Expanded(child: b),
        ],
      ]);
      if (needed <= available || available <= 0) return row;
      return MediaQuery(
        data: MediaQuery.of(context).copyWith(textScaler: TextScaler.linear(scaler.scale(1) * available / needed)),
        child: row,
      );
    });
  }
"""
assert old in s
s=s.replace(old,new)
s=s.replace("""          fitLabel: !stacked,
""","""          singleLine: !stacked,
""")
s=s.replace("""    required this.fitLabel,
""","""    required this.singleLine,
""")
s=s.replace("""  /// Sur une ligne, le libellé se réduit plutôt que de couper un mot
  /// (« Maîtrisé » à 1,6× sur 375 pt de large).
  final bool fitLabel;""","""  /// Sur une ligne (barre horizontale), le libellé ne passe jamais à la ligne.
  final bool singleLine;""")
s=s.replace("""  static const _horizontalPadding = CgSpace.s2;
  static const _verticalPadding = CgSpace.s2;
""","""  static const _horizontalPadding = CgSpace.s2;
  static const _verticalPadding = CgSpace.s2;

  /// Largeur non disponible pour le libellé : marges internes + contour 1 pt.
  static const chrome = 2 * _horizontalPadding + 2;
""")
s=s.replace("""    final Widget text0 = Text(
      label,
      style: CgType.head.copyWith(color: text),
      textAlign: TextAlign.center,
      maxLines: widget.fitLabel ? 1 : 2,
      overflow: widget.fitLabel ? TextOverflow.visible : TextOverflow.ellipsis,
    );
""","""    final Widget labelText = Text(
      label,
      style: CgType.head.copyWith(color: text),
      textAlign: TextAlign.center,
      maxLines: widget.singleLine ? 1 : 2,
      softWrap: !widget.singleLine,
      overflow: TextOverflow.ellipsis,
    );
""")
s=s.replace("""                  child: widget.fitLabel ? FittedBox(fit: BoxFit.scaleDown, child: text0) : text0,""","""                  child: labelText,""")
open(p,'w').write(s)
